"""Independent reference: IPv6 LPM and canonical SCAMP image builder (Python)."""
import json

def norm(addr, length):
    v = int(addr, 16)
    if length == 0: return 0
    return v >> (128 - length) << (128 - length)

def lpm(fib, addr_int):
    """fib: {(prefix_int,length): hop}; returns hop or None."""
    for l in range(128, -1, -1):
        p = addr_int >> (128 - l) << (128 - l) if l else 0
        h = fib.get((p, l))
        if h is not None: return h
    return None

def bit(v, i):  # bit i of a 128-bit int, MSB first
    return (v >> (127 - i)) & 1

def bits(v, d, n):
    if n <= 0: return 0
    return (v >> (128 - d - n)) & ((1 << n) - 1)

def mask(v, length):
    if length <= 0: return 0
    return v >> (128 - length) << (128 - length)

# ---------------------------------------------------------------- graph

class Node:
    __slots__ = ('origin','level','depth','type','region','pfx','children','keys','bmp',
                 'stage','cell','span','bulk','ni_bitmap','ni_count','bitmap_id','ni_base',
                 'maxlen')
    def __init__(self, origin, level, region, maxlen):
        self.origin = origin; self.level = level; self.depth = origin + 6*level
        self.region = region; self.maxlen = maxlen
        self.pfx = []; self.children = []; self.keys = []
        self.bmp = None; self.stage = 0; self.cell = 0; self.span = 0
        self.bulk = False; self.ni_bitmap = 0; self.ni_count = 0
        self.bitmap_id = 0; self.ni_base = 0

def build_forest(prefixes, origin, region, maxlen, level, pool):
    # prefixes: list of (prefix128, len, hop) already owned by this forest
    n = Node(origin, level, region, maxlen)
    pool.append(n)
    if len(prefixes) <= 2:
        n.type = 4 if len(prefixes) == 1 else 5
        n.pfx = list(prefixes)
        return n
    depth = n.depth
    local = []
    buckets = {}
    for p in prefixes:
        if p[1] < depth + 6: local.append(p)
        else: buckets.setdefault(bits(p[0], depth, 6), []).append(p)
    local.sort(key=lambda p: (1 << (p[1]-depth)) + bits(p[0], depth, p[1]-depth))
    n.pfx = local
    n.ni_count = len(local)
    for p in local:
        n.ni_bitmap |= 1 << ((1 << (p[1]-depth)) + bits(p[0], depth, p[1]-depth))
    for k in sorted(buckets):
        cr = region | (k << (128 - depth - 6))
        n.children.append(build_forest(buckets[k], origin, cr, maxlen, level+1, pool))
        n.keys.append(k)
    c = len(n.children)
    n.type = 1 if c <= 2 else (2 if c <= 6 else 3)
    return n

def build_graph(fib):
    """fib: {(prefix,len): hop} -> (roots, fronts, pool)"""
    pool = []
    g0 = [ (p, l, h) for (p,l),h in fib.items() if l <= 16 ]
    m16 = {}; m64 = {}
    for (p,l),h in sorted(fib.items()):
        if 16 < l <= 64: m16.setdefault(p >> 112, []).append((p,l,h))
        elif l > 64: m64.setdefault(p >> 64, []).append((p,l,h))
    root0 = build_forest(sorted(g0), 0, 0, 16, 0, pool) if g0 else None
    f16 = [(k, build_forest(m16[k], 16, k << 112, 64, 0, pool)) for k in sorted(m16)]
    f64 = [(k, build_forest(m64[k], 64, k << 64, 128, 0, pool)) for k in sorted(m64)]
    for n in pool:
        best = None; bestlen = -1
        for l in range(n.depth, -1, -1):
            h = fib.get((mask(n.region, l), l))
            if h is not None: best, bestlen = h, l; break
        n.bmp = best
    return root0, f16, f64, pool

# ---------------------------------------------------------------- packing

def keep_top64(v, n):
    if n <= 0: return 0
    if n >= 64: return v
    return (v >> (64-n)) << (64-n)

def frag_of(p, origin):
    rel = p[1] - origin
    if origin == 0: return keep_top64(p[0] >> 64, rel)
    if origin == 16: return ((p[0] >> (128-16-rel)) & ((1 << rel)-1)) << (64-rel)
    return keep_top64(p[0] & ((1<<64)-1), rel)

def child32(key, stage, cell):
    return (key & 0x3F) | ((stage & 0xF) << 6) | ((cell & 0x3FFFFF) << 10)

ABSENT = 15 << 6

def pack(node, stage_of, cell_of, bitmaps, nexthops, direct_keys=()):
    """Return a list of 128-bit ints (cells) for this node's record."""
    fields = []
    def w(v, n):
        fields.append((v & ((1 << n)-1 if n < 64 else (1<<64)-1), n))
    w(node.type, 3)
    w(4194303 if node.bmp is None else node.bmp, 22)
    if node.type in (4,5):
        cnt = 1 if node.type == 4 else 2
        for i in range(cnt):
            p = node.pfx[i]
            w(frag_of(p, node.origin), 64)
            w(p[1]-node.origin, 8)
            w(p[2], 22)
        w(0, 9 if node.type == 4 else 43)
    else:
        w(bitmaps.index(node.ni_bitmap) if node.ni_bitmap in bitmaps else 0, 16)
        w(node.ni_base, 22)
        if node.type in (1,2):
            slots = 2 if node.type == 1 else 6
            present = [ (k, cell_of(c)) for k,c in zip(node.keys, node.children) ]
            for i in range(slots):
                if i < len(present):
                    w(child32(present[i][0], stage_of(node.children[i]), present[i][1]), 32)
                else:
                    w(ABSENT, 32)
            w(0, 1)
        else:
            bulk_keys = [k for k in node.keys if k not in direct_keys]
            bm = 0
            for k in bulk_keys: bm |= 1 << k
            base = cell_of(node.children[node.keys.index(bulk_keys[0])]) if bulk_keys else 0
            w(bm, 64)
            w(base, 22)
            w(stage_of(node.children[node.keys.index(bulk_keys[0])]) if bulk_keys else 0, 4)
            directs = [k for k in node.keys if k in direct_keys]
            for i in range(3):
                if i < len(directs):
                    k = directs[i]; c = node.children[node.keys.index(k)]
                    w(child32(k, stage_of(c), cell_of(c)), 32)
                else:
                    w(ABSENT, 32)
            w(0, 7)
    # assemble into 128-bit cells
    total = 128 if node.type in (1,4) else 256
    val = 0; pos = 0
    for v, n in fields:
        val |= v << pos
        pos += n
    assert pos == total, (node.type, pos, total)
    if total == 128: return [val]
    return [val & ((1<<128)-1), val >> 128]

def build_image(fib, stage_policy='top', place_order='bulk-first',
                ni_order='stage-cell', direct_count=0, type5_reverse=False):
    """Build a valid image JSON from a FIB using configurable legal choices."""
    root0, f16, f64, pool = build_graph(fib)
    # stage policy
    if stage_policy == 'top':
        for n in pool: n.stage = 10 - n.level
    else:  # 'height': leaves at 0, parents above
        def height(n):
            if not n.children: return 0
            return 1 + max(height(c) for c in n.children)
        hs = {}
        for n in pool:
            h = height(n)
            hs.setdefault(h, []).append(n)
        maxh = max(hs) if hs else 0
        for h, ns in hs.items():
            for n in ns: n.stage = min(10, maxh - h)
    # bulk / direct children
    for n in pool:
        if n.type == 3:
            nd = min(direct_count, len(n.keys) - 4) if direct_count else 0
            nd = max(0, nd)
            n.direct = set(n.keys[:nd])
    # placement
    by_stage = {}
    for n in pool: by_stage.setdefault(n.stage, []).append(n)
    groups = {}
    for n in pool:
        if n.type == 3:
            bulk = [c for k, c in zip(n.keys, n.children) if k not in n.direct]
            for c in bulk: c.bulk = True
            groups.setdefault(n.stage - 1, []).append(bulk)
    cells = {}
    for s in range(11):
        off = 0
        seq = []
        if place_order == 'bulk-first':
            for grp in groups.get(s, []):
                for c in grp: seq.append((c, 2))
            for n in by_stage.get(s, []):
                if not n.bulk and n.type in (2,3,5): seq.append((n, 2))
            for n in by_stage.get(s, []):
                if not n.bulk and n.type in (1,4): seq.append((n, 1))
        else:  # full-first
            for n in by_stage.get(s, []):
                if not n.bulk and n.type in (2,3,5): seq.append((n, 2))
            for grp in groups.get(s, []):
                for c in grp: seq.append((c, 2))
            for n in by_stage.get(s, []):
                if not n.bulk and n.type in (1,4): seq.append((n, 1))
        for n, span in seq:
            n.cell = off; n.span = span; off += span
        cells[s] = off
    # NI vector + dictionary
    order = [n for n in pool if n.type in (1,2,3)]
    if ni_order == 'stage-cell':
        order.sort(key=lambda n: (n.stage, n.cell))
    elif ni_order == 'reverse':
        order.sort(key=lambda n: (n.stage, n.cell), reverse=True)
    else:
        order.sort(key=lambda n: (n.ni_bitmap, n.stage, n.cell))
    nexthops = []
    for n in order:
        if n.ni_count:
            n.ni_base = len(nexthops)
            for p in n.pfx: nexthops.append(p[2])
        else:
            n.ni_base = 0
    bitmaps = sorted(set(n.ni_bitmap for n in order))
    for n in order: n.bitmap_id = bitmaps.index(n.ni_bitmap)
    # pack
    banks = [ [0]*((cells[s]+1)//2) for s in range(11) ]
    def stage_of(n): return n.stage
    def cell_of(n): return n.cell
    for n in pool:
        if type5_reverse and n.type == 5:
            n.pfx = [n.pfx[1], n.pfx[0]]
        rec = pack(n, stage_of, cell_of, bitmaps, nexthops,
                   getattr(n, 'direct', set()))
        row = n.cell // 2
        if len(rec) == 1:
            if n.cell % 2: banks[n.stage][row] |= rec[0] << 128
            else: banks[n.stage][row] |= rec[0]
        else:
            assert n.cell % 2 == 0
            banks[n.stage][row] = rec[0] | (rec[1] << 128)
    out = {"root": None if root0 is None else [root0.stage, root0.cell],
           "front16": [[f"{k:04x}", c.stage, c.cell] for k, c in f16],
           "front64": [[f"{k:016x}", c.stage, c.cell] for k, c in f64],
           "cells": [cells[s] for s in range(11)],
           "banks": [[f"{w:064x}" for w in banks[s]] for s in range(11)],
           "bitmaps": [f"{b:016x}" for b in bitmaps],
           "nexthops": list(nexthops)}
    return out
